<script setup lang="ts">
import { onUnmounted, watch } from 'vue'
import type { ReviewWorkspaceApi, SessionData } from '../reviews/client'
import { useRelease, withdrawalReasons } from './useRelease'
const props = defineProps<{ api: ReviewWorkspaceApi; actor: SessionData; canPublish: boolean; canWithdraw: boolean }>()
const emit = defineEmits<{ sessionExpired: [] }>()
const model = useRelease(props.api, () => emit('sessionExpired')), state = model.state
watch(() => [props.actor, props.canPublish, props.canWithdraw] as const, ([actor, publish, withdraw]) => model.setAccess(actor, publish, withdraw), { immediate: true }); onUnmounted(model.dispose)
</script>
<template>
  <section class="rw-card" data-testid="release-panel" aria-labelledby="release-title" :aria-busy="!!state.busy">
    <h3 id="release-title">03 / 预检、原子发布与撤回</h3><p>审核不等于公开许可。每次提交会重新检查当前批准、来源公开使用许可、文件期限和全部版本；合成只可 test_fixture，规则版本仍 null。</p>
    <div class="rw-grid"><label>确切数据集 UUID<input v-model="state.datasetId" data-testid="release-dataset" :disabled="!!state.busy" @input="model.scopeChanged"></label><label>明确入学年度<input v-model="state.year" data-testid="release-year" type="number" min="1" max="9999" step="1" :disabled="!!state.busy" @input="model.scopeChanged"></label></div><button type="button" data-testid="release-load-current" :disabled="!!state.busy" @click="model.loadCurrent">读取当前发布头与数据集版本</button>
    <p v-if="state.message" class="rw-message" :class="{ error: state.error }" :role="state.error ? 'alert' : 'status'">{{ state.message }}</p>
    <div v-if="state.head" class="rw-output" data-testid="release-current"><strong>服务器数据集 revision {{ state.head.dataset_revision }}</strong><template v-if="state.head.release"><p>release {{ state.head.release.release_id }} / 版本 {{ state.head.release.version }} / state {{ state.head.release.state }} / revision {{ state.head.release.state_revision }}</p><p>{{ state.head.release.kind }} · 成员 {{ state.head.release.member_count }} · {{ state.head.release.valid_from }} ≤ UTC &lt; {{ state.head.release.valid_until }}</p><code>{{ state.head.release.requirements_version }}</code></template><p v-else>当前没有 published 头；不代表存在完整资料覆盖。</p></div>
    <template v-if="canPublish">
      <fieldset :disabled="!!state.busy" @input="model.changed" @change="model.changed"><legend>精确发布成员与有效窗口</legend><div class="rw-grid"><label>发布通道<select v-model="state.kind" data-testid="release-kind"><option disabled value="">明确选择</option><option v-if="actor.is_synthetic" value="test_fixture">test_fixture · 仅合成隔离验收</option><option v-else value="formal">formal · 仍受真实门槛</option></select></label><label class="rw-check"><input v-model="state.replace" type="checkbox" data-testid="release-replace"><span>明确替代已读取的当前 published 版本及确切 state revision。未选择则不静默替代。</span></label><label>公开版本生效时刻（RFC3339，须带偏移）<input v-model="state.validFrom" data-testid="release-valid-from" placeholder="YYYY-MM-DDTHH:mm:ssZ" autocomplete="off"></label><label>公开版本失效时刻（不含，须带偏移）<input v-model="state.validUntil" data-testid="release-valid-until" placeholder="YYYY-MM-DDTHH:mm:ssZ" autocomplete="off"></label></div><p>这是公开版本有效期，不是学校招生截止时间；不自动补日期、23:59 或时区。当前不支持预定发布。</p>
        <div v-for="(item, index) in state.members" :key="index" class="rw-output"><h4>成员 {{ index + 1 }} / 最多 50</h4><div class="rw-grid"><label>候选 fact UUID<input v-model="item.factId" :data-testid="`release-member-fact-${index}`" autocomplete="off"></label><label>当前批准 case revision<input v-model="item.caseRevision" :data-testid="`release-member-case-${index}`" type="number" min="1" step="1"></label><label class="rw-wide">当前批准 decision UUID<input v-model="item.decisionId" :data-testid="`release-member-decision-${index}`" autocomplete="off"></label></div><label class="rw-check"><input v-model="item.publicEvidence" type="checkbox" :data-testid="`release-member-public-${index}`"><span>明确允许这个成员的有界证据片段进入公共投影（默认不公开）</span></label><button type="button" :disabled="state.members.length <= 1" @click="model.removeMember(index)">移除成员</button></div>
      </fieldset><button type="button" data-testid="release-member-add" :disabled="!!state.busy || state.members.length >= 50" @click="model.addMember">明确添加一个成员</button>
      <label class="rw-check"><input v-model="state.precheckConfirmed" data-testid="release-precheck-confirm" type="checkbox" :disabled="!!state.busy"><span>确认以这个精确 payload 进行当前发布预检，未创建 release。</span></label><button type="button" data-testid="release-precheck" :disabled="!model.canPrecheck()" @click="model.precheck">确认当前发布预检</button>
      <div v-if="state.precheck" class="rw-output" data-testid="release-precheck-result"><strong>precheck_passed · 当前诊断，不是永久许可</strong><p>检查时间 {{ state.precheck.checked_at }} · dataset revision {{ state.precheck.dataset_revision }} · 成员 {{ state.precheck.member_count }}</p><code>{{ state.precheck.request_sha256 }}</code></div>
      <label class="rw-check"><input v-model="state.publishConfirmed" data-testid="release-publish-confirm" type="checkbox" :disabled="!!state.busy || !state.precheck"><span>我确认实际原子发布这些确切成员。提交时重新核验；修改 payload 必须重新预检。</span></label><button type="button" data-testid="release-publish" :disabled="!model.canPublishNow()" @click="model.publish">确认提交原子发布</button>
    </template>
    <section v-if="canWithdraw" class="rw-output"><h4>撤回当前发布 · 独立减权操作</h4><p>旧资料或批准失效不应阻止有权撤回；仍需要当前强管理员、当前头和确切 state CAS。</p><label>明确撤回理由<select v-model="state.withdrawalReason" data-testid="release-withdraw-reason" :disabled="!!state.busy" @change="model.withdrawalChanged"><option disabled value="">选择有限理由</option><option v-for="reason in withdrawalReasons" :key="reason" :value="reason">{{ reason }}</option></select></label><label class="rw-check"><input v-model="state.withdrawConfirmed" type="checkbox" data-testid="release-withdraw-confirm" :disabled="!!state.busy || !state.head?.release"><span>确认撤回已读取的当前 release，不删除历史，也不自动重启旧版。</span></label><button type="button" data-testid="release-withdraw" :disabled="!model.canWithdrawNow()" @click="model.withdraw">确认撤回当前版本</button></section>
    <div v-if="state.result" class="rw-output" data-testid="release-result"><strong>服务器回执 {{ state.result.release_id }}</strong><p>state {{ state.result.state }} / revision {{ state.result.state_revision }} / {{ state.result.kind }} · 幂等回放 {{ state.result.replayed }}</p><p>requirements_version {{ state.result.requirements_version }} · ruleset_version=null</p><p>请另外读取匿名公共投影，不以此回执代替当前公开内容。</p></div>
  </section>
</template>
